SELECT VERSION() AS version;
SHOW GLOBAL STATUS LIKE 'Uptime';
SHOW GLOBAL STATUS LIKE 'Threads_connected';

SHOW GLOBAL STATUS LIKE 'Threads_connected';
SHOW GLOBAL STATUS LIKE 'Threads_running';
SHOW VARIABLES LIKE 'max_connections';
SELECT COUNT(*) AS processlist_count FROM information_schema.PROCESSLIST;

SHOW VARIABLES LIKE 'slow_query_log';
SHOW VARIABLES LIKE 'long_query_time';
SHOW VARIABLES LIKE 'slow_query_log_file';
SHOW VARIABLES LIKE 'log_queries_not_using_indexes';

SHOW VARIABLES LIKE 'event_scheduler';
SHOW EVENTS;
SELECT EVENT_SCHEMA, EVENT_NAME, STATUS, LAST_EXECUTED FROM information_schema.EVENTS LIMIT 20;

SHOW GLOBAL STATUS LIKE 'Questions';
SHOW GLOBAL STATUS LIKE 'Com_commit';
SHOW GLOBAL STATUS LIKE 'Com_rollback';
SHOW GLOBAL STATUS LIKE 'Uptime';

SHOW GLOBAL STATUS LIKE 'Created_tmp%';
SHOW GLOBAL STATUS LIKE 'Sort_merge_passes';
SHOW GLOBAL STATUS LIKE 'Sort_scan';
SHOW GLOBAL STATUS LIKE 'Sort_range';

SELECT @@innodb_buffer_pool_size / 1024 / 1024 / 1024 AS buffer_pool_gb;
SHOW VARIABLES LIKE 'innodb_buffer_pool_instances';
SHOW GLOBAL STATUS LIKE 'Innodb_buffer_pool_pages_total';

SELECT INDEX_NAME, IS_VISIBLE FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = '<db>' AND TABLE_NAME = '<table>' LIMIT 50;
-- 设为不可见（仅 8.0+，灰度验证用）：
-- ALTER TABLE <db>.<table> ALTER INDEX <index> INVISIBLE;
-- 恢复可见：ALTER TABLE <db>.<table> ALTER INDEX <index> VISIBLE;

-- shell: mysqldumpslow -s t -t 20 "<slow_log路径>"
-- shell: pt-query-digest --type slowlog "<slow_log路径>" | head -n 100
SHOW VARIABLES LIKE 'slow_query_log_file';

-- 8.0.18+ 才有 EXPLAIN ANALYZE；5.7/8.0.17 及以下只能用 EXPLAIN。
-- EXPLAIN ANALYZE 会真实执行 SQL，只对 SELECT 用，不要对 UPDATE/DELETE 用。
EXPLAIN <SELECT 语句>;
-- EXPLAIN ANALYZE <SELECT 语句>;

-- 先查，再杀：
SELECT ID, USER, HOST, DB, COMMAND, TIME, STATE, INFO FROM information_schema.PROCESSLIST WHERE TIME > 300 ORDER BY TIME DESC LIMIT 20;
-- DANGER: 先确认该连接的业务影响，再执行下面一行，<connection_id> 填上面查到的 ID：
-- KILL CONNECTION <connection_id>;

SHOW VARIABLES LIKE 'innodb_data_file_path';
SHOW VARIABLES LIKE 'innodb_data_home_dir';
SHOW VARIABLES LIKE 'innodb_undo_directory';
SHOW VARIABLES LIKE 'innodb_log_file_size';
SHOW VARIABLES LIKE 'innodb_log_files_in_group';
SHOW VARIABLES LIKE 'innodb_log_group_home_dir';

-- shell: python binlog2sql.py -h<host> -u<user> -d<db> -t<table> --start-file="<binlog文件>" --start-datetime="2026-11-24 10:00:00" --stop-datetime="2026-11-24 11:00:00" -B
-- 闪回只对 DML 有效，先确认：
SHOW VARIABLES LIKE 'binlog_format';

-- 5.7: SHOW SLAVE STATUS
-- 8.0+: SHOW REPLICA STATUS（5.7 的 SHOW SLAVE STATUS 在 8.0 仍可用，8.4 已移除）
SHOW SLAVE STATUS;

SHOW VARIABLES LIKE 'gtid_mode';
SHOW VARIABLES LIKE 'enforce_gtid_consistency';
SELECT @@GLOBAL.gtid_executed AS gtid_executed;
SELECT @@GLOBAL.gtid_purged AS gtid_purged;

-- 先查当前主节点 UUID：
SELECT MEMBER_ID, MEMBER_HOST, MEMBER_ROLE FROM performance_schema.replication_group_members;
